"""Bounded review of nine coating-test objects, supplements and reuse uncertainty."""
import html,json,re
import ledger as L
from review_batch_0001 import evidence

def main():
 key='10.1038/ncomms15654';rid='author-priority-william-shih';batch='AUTHOR0008';before=L.counts();base=L.ROOT/'assets/research-20261105';folder=base/'shih-extracted/34'
 archive=next(a for a in json.loads((L.HERE/'shih_source_archive_inventory.json').read_text()) if a['ordinal']==34)['archive'];url=archive['url']
 main=evidence(folder/'PonnuswamyN_ncomm_2017.pdf',url,'Mainp1 date; pp3–7 design/coating/results and synthesis; Fig2 visually inspected; references18/19')
 si=evidence(folder/'PonnuswamyN_ncomm_2017_SI.pdf',url,'Fig23/24 DN9 captions; Figs41–48 indexed at PDF/printedpp40–47. Fig41 DN1 andFig42 DN2 visually inspected; other routing figures not yet individually reviewed.')
 pub=evidence(base/'ponnuswamy-publisher.html','https://www.nature.com/articles/ncomms15654','Supplementary information captions map Data1–9 toDN1–9 andData10 toCy3/Cy5 DN1; references1–32')
 idx=json.loads((L.HERE/'ponnuswamy_sequence_index.json').read_text());seq=[w['evidence'] for w in idx['workbooks']]
 notes='Nine coating-test objects DN1–DN9. MainFig2 shows DN1–DN4 barrel/ring variants, DN5 planar rectangular object, DN6/DN7 rod-like objects andDN8 octahedral frame; these visual descriptors do not establish independent new designs. Main methods specify p7308 scaffold. SI Figs41–48 provide caDNAno diagrams forDN1–DN8; DN1/DN2 panels visually inspected and contain numbered helix cross-section motifs and flattened paths, while exact native routing/lattice and other panels remain unchecked. Data1–9 map toDN1–DN9; cell-index counts are324,162,408,342,175,154,120,156,187 sequence-like cells, respectively. Data9 also has two nonsequence footer cells. Data10 contains36 modified sequences(18Cy3,18Cy5), not a full new core design. These counts do not certify staple roles or complete synthesis sets.'
 conflict='DN9 is explicitly described as a polyhedral mesh helix in mainp4, citing ref19(Veneziano2016). Its Data9 workbook A94 instead contains doi:10.1038/nature14586(Benson2015), with a source-page footer inA93. Exact upstream design attribution and whether this is a reused sequence table require reconciliation; do not silently choose one source.'
 follow=['Inspect DN3–DN8 diagrams individually and verify lattice, scaffold identity, strand roles, native routing and sequence-to-variant correspondence.','Reconcile DN9 citation/workbook provenance discrepancy and exact upstream design.','Compare2019 MeRPy p3315 barrel+miniscaffold to2017 DN1/DN2 p7308 designs; the citation alone does not identify an exact sequence-equivalent object.','Follow32 backward references and forward citations; check complete native design assets and all functionalized variants.']
 p=next(p for p in L.read('publication_reviews') if p['registry_key']==key)
 for e in [main,si,pub]+seq:
  if e not in p['evidence']:p['evidence'].append(e)
 p.update(title='Oligolysine-based coating protects DNA nanostructures from low-salt denaturation and nuclease degradation',publication_type=['journal_article'],review_stage='design_sources_reviewed',relevance='design_bearing',design_contributions=['modified_design','reused_design','uncertain'],catalog_eligibility='unresolved',access='main_SI_and_ten_sequence_workbooks_available',rationale=notes+' '+conflict,reviewer='Codex primary source, two routing figures and all workbook cell inspection',run_id=rid,date=L.DATE,date_evidence={'date':'2017-05-31','source':main,'primary_verified':True,'meaning':'Published date on mainp1'},unresolved_questions=follow)
 L.upsert('publication_reviews',p,'Review coating-test objects and bounded source evidence')
 for did,names,decision,eligible,note in [('RDE0045',[f'DN{i}' for i in range(1,9)],'Unresolved per object; cross-section/path diagrams exist, DN1/DN2 inspected but native routing verification pending','unresolved',notes),('RDE0046',['DN9 mesh helix'],'Explicit polyhedral mesh architecture(mainp4); outside narrow standard-lattice catalog scope','excluded',conflict)]:
  old=next((d for d in L.read('design_evidence') if d['design_id']==did),None)
  if old:assert key in old['publication_keys']
  L.upsert('design_evidence',dict(design_id=did,publication_keys=[key],named_objects=names,identity_status='Paper-labelled source-review group; exact upstream identities and variant deduplication pending',lattice_decision=decision,catalog_eligibility=eligible,core_variant_composition=note,relationships=[],variant_links=[],source_completeness='not_verified',evidence=[main,si,pub]+seq,source_files=[archive,main,si]+seq,outstanding_checks=follow,review_stage='source_reviewed',review_run=batch,run_id=rid,date=L.DATE,legacy_record={}), 'Preserve literature relevance separately from narrow catalog eligibility')
 merpy=next(d for d in L.read('design_evidence') if d['design_id']=='RDE0043')
 merpy['upstream_source_check']='2017 parent main/SI and10 sequence workbooks recovered from Shih. Main methods specify p7308;2019 barrel uses3315nt product plus miniscaffold. Exact parent DN label and corresponding strand pools remain unverified.'
 if main not in merpy['evidence']:merpy['evidence'].append(main)
 L.upsert('design_evidence',merpy,'Record recovered parent sources without assuming exact barrel equivalence')
 text=(base/'ponnuswamy-publisher.html').read_text();refs=list(re.finditer(r'<p[^>]*id="ref-CR(\d+)"[^>]*>(.*?)</p>',text,re.S));assert [int(m[1]) for m in refs]==list(range(1,33))
 for m in refs:
  n=m[1];citation=html.unescape(re.sub('<[^>]*>','',m[2]))
  L.upsert('discovery_edges',dict(edge_id='ponnuswamy2017:reference:'+n,source_key=key,target_key='citation:ponnuswamy2017:'+n,relation='cites',evidence_url=pub['url'],local_file=pub['local_file'],sha256=pub['sha256'],locator='reference'+n,citation=citation,reconciliation_state='pending_identity_reconciliation',run_id=rid,date=L.DATE),'Retain all32 primary references without relevance cap')
 invpath=L.HERE/'shih_bibliography_inventory.json';inv=json.loads(invpath.read_text());row=next(r for r in inv['entries'] if r['ordinal']==34);row.update(review_status='main_SI_two_routing_panels_and_ten_workbooks_reviewed; source_completeness_unverified',target_key=key,identity_status='primary_title_doi_date_verified');L.atomic(invpath,json.dumps(inv,indent=2)+'\n')
 L.upsert('batches',dict(batch_id=batch,date=L.DATE,status='completed',input_keys=[key],selection='Recovered Shih source archive; explicit upstream MeRPy design reference',completed_actions=['Inspected main design/method evidence, Fig2, SI DN9 descriptions and DN1/DN2 diagrams; indexed all10 workbooks by cell.','Recorded DN1–DN8 source group and separately catalog-excluded but literature-relevant DN9 mesh object; exact identities pending.','Preserved DN9 provenance conflict and MeRPy scaffold mismatch; retained all32 backward references.'],before_counts=before,after_counts=L.counts(),unresolved_keys=[key],exclusion_audit={'sample':[{'design_id':'RDE0046','reason':'Explicit polyhedral mesh in primary mainp4; literature retained, narrow catalog exclusion only','evidence':main}],'denominator':1,'meaning':'One new design-level catalog exclusion audited; no publication exclusions'},validation=[L.validate()],next_queue=follow+['Review acquired Hahn2019 and Krieg2018 sources; rotate other named-author histories.']), 'Save bounded multi-design source review and unresolved cases')
 print(L.validate())
if __name__=='__main__':main()
